import type { Problem, ContestProblem, SubmissionDetailResponse, SubmissionDiagnosticUpdateEvent, SubmissionCorrectionUpdateEvent } from './api-contract';

export const ideBridgeProtocol = 'shortestpath-oj-v2';
export const ideBridgeVersion = 2;
export const ideBridgeFeatures = ['public-problem', 'context', 'submission-history', 'diagnostic', 'correction', 'connection-recovery', 'workspace-modes'] as const;

export type SolveTarget =
  | { kind: 'training' | 'standalone'; problemId: string; problemRef: string }
  | { kind: 'contest'; problemId: string; contestId: string; contestRef: string; contestProblemId: string; problemLabel: string };

export type PublicProblemContent = Problem | ContestProblem;
export type BridgeSubmissionDetail = SubmissionDetailResponse;
export type BridgeDiagnosticSnapshot = SubmissionDiagnosticUpdateEvent;
export type BridgeCorrectionSnapshot = SubmissionCorrectionUpdateEvent;

export function solveContextRef(target: SolveTarget): string {
  return target.kind === 'contest' ? `contest/${target.contestRef}/${target.problemLabel}` : target.problemRef;
}

export function isOrdinaryLocalTest(problem: PublicProblemContent): boolean {
  const runtime = problem.judge_runtime;
  return !problem.interaction && !problem.local_judging
    && (!runtime || (runtime.execution_mode === 'batch' && runtime.build_mode === 'standalone' && runtime.evaluation_mode === 'tokens'))
    && ['default', 'tokens', 'token', ''].includes(problem.checker_type);
}

// Recovery tickets are issued by the IDE, scoped to the selected account and solve target.
